&lt;label for="name" class="form-label"&gt;Your name&lt;/label&gt;
&lt;input type="text" class="form-control" id="name"
       name="name" required&gt;


&lt;label for="email" class="form-label"&gt;ryand25@tcd.ie&lt;/label&gt;
&lt;input type="email" class="form-control" id="email"
       name="email" required&gt;


&lt;label for="interest" class="form-label"&gt;What are you interested in?&lt;/label&gt;
&lt;select class="form-select" id="interest" name="interest" required&gt;
  &lt;option value=""&gt;Please select&lt;/option&gt;
  &lt;option&gt;Pronunciation coaching&lt;/option&gt;
  &lt;option&gt;General English&lt;/option&gt;
  &lt;option&gt;Professional communication&lt;/option&gt;
  &lt;option&gt;Workshops and training&lt;/option&gt;
  &lt;option&gt;English in Wicklow&lt;/option&gt;
  &lt;option&gt;Other&lt;/option&gt;
&lt;/select&gt;


&lt;label for="message" class="form-label"&gt;Your message&lt;/label&gt;
&lt;textarea class="form-control" id="message"
          name="message" rows="6"
          placeholder="Tell me a little about what you're looking for..."
          required&gt;&lt;/textarea&gt;



